let seed = 42;
const rnd = () => { seed = (seed * 1664525 + 1013904223) % 4294967296; return seed / 4294967296; };
const noise = () => 0.9 + rnd() * 0.2;
const iso = (d) => d.toISOString().slice(0, 10);
const today = new Date();
const days = [];
for (let i = 35; i >= 1; i--) { const d = new Date(Date.UTC(today.getUTCFullYear(), today.getUTCMonth(), today.getUTCDate() - i)); days.push(iso(d)); }

const campaigns = [
  { platform: 'google_ads', id: '111', name: 'Search - Brand', spend: 30, roas: 6.0, cpc: 0.9 },
  { platform: 'google_ads', id: '112', name: 'Search - Generic', spend: 55, roas: 2.6, cpc: 1.4 },
  { platform: 'google_ads', id: '113', name: 'Performance Max - Catalog', spend: 45, roas: 3.0, cpc: 1.0 },
  { platform: 'meta_ads', id: '201', name: 'Prospecting - Lookalike', spend: 45, roas: 2.2, cpc: 0.8 },
  { platform: 'meta_ads', id: '202', name: 'Retargeting - 14 days', spend: 25, roas: 4.0, cpc: 0.7 },
];
const AOV = 80;
const rows = [];
const adClicks = {};
days.forEach((date, idx) => {
  const last = idx === days.length - 1;
  for (const c of campaigns) {
    let spend = c.spend * noise(), roas = c.roas * noise();
    if (last && c.id === '201') { spend *= 2.8; roas *= 0.2; }
    if (last && c.id === '112') { spend *= 1.3; roas *= 0.25; }
    const revenue = spend * roas;
    const clicks = Math.round(spend / c.cpc);
    rows.push({ type: 'ads', platform: c.platform, date, campaignId: c.id, campaignName: c.name, spend: Math.round(spend * 100) / 100, clicks, impressions: clicks * 40, conversions: Math.round((revenue / AOV) * 10) / 10, revenue: Math.round(revenue * 100) / 100 });
    const k = `${c.platform}|${date}`; adClicks[k] = (adClicks[k] || 0) + clicks;
  }
  for (const ch of ['google_ads', 'meta_ads']) {
    let sessions = adClicks[`${ch}|${date}`] * 0.85 * noise();
    if (last && ch === 'meta_ads') sessions *= 0.2;
    rows.push({ type: 'ga4', channel: ch, date, sessions: Math.round(sessions), conversions: Math.round(sessions * 0.03), revenue: Math.round(sessions * 2.4) });
  }
});
return rows.map((r) => ({ json: r }));

const cfg = $('Workflow Configuration').first().json;
const rows = $input.all().map((i) => i.json);
const ads = rows.filter((r) => r.type === 'ads');
const ga = rows.filter((r) => r.type === 'ga4');
const n = (x) => Number(x) || 0;
const mean = (a) => (a.length ? a.reduce((s, x) => s + x, 0) / a.length : 0);
const sd = (a) => { const m = mean(a); return Math.sqrt(mean(a.map((x) => (x - m) ** 2))); };
const r2 = (x) => Math.round(x * 100) / 100;
const LABEL = { google_ads: 'Google Ads', meta_ads: 'Meta Ads' };
const Z = n(cfg.zThreshold) || 2.5, BASE = n(cfg.baselineDays) || 14, MIN = n(cfg.minDailySpend), TARGET = n(cfg.targetRoas);

if (!ads.length) {
  return [{ json: { kind: 'digest', subject: 'Ad monitor: no data returned', body: 'No ad rows were returned. Check credentials, IDs and the date range in Workflow Configuration.', counts: {} } }];
}
const dates = [...new Set(ads.map((r) => r.date))].sort();
const latest = dates[dates.length - 1];
const findings = [], actions = [];

const camps = {};
for (const r of ads) {
  const k = `${r.platform}|${r.campaignId}`;
  camps[k] = camps[k] || { platform: r.platform, id: r.campaignId, name: r.campaignName, byDate: {} };
  const d = (camps[k].byDate[r.date] = camps[k].byDate[r.date] || { spend: 0, rev: 0, conv: 0, clicks: 0 });
  d.spend += n(r.spend); d.rev += n(r.revenue); d.conv += n(r.conversions); d.clicks += n(r.clicks);
}

for (const c of Object.values(camps)) {
  const cur = c.byDate[latest];
  if (!cur || cur.spend < MIN) continue;
  const hist = Object.keys(c.byDate).filter((d) => d < latest).sort().slice(-BASE);
  if (hist.length < 7) continue;
  const spendH = hist.map((d) => c.byDate[d].spend);
  const roasH = hist.filter((d) => c.byDate[d].spend > 0).map((d) => c.byDate[d].rev / c.byDate[d].spend);
  const sM = mean(spendH), sS = Math.max(sd(spendH), 0.1 * sM);
  const rM = mean(roasH), rS = Math.max(sd(roasH), 0.1 * rM);
  const roas = cur.rev / cur.spend;
  const zS = (cur.spend - sM) / sS, zR = rS > 0 ? (roas - rM) / rS : 0;
  const spike = zS >= Z, drop = zR <= -Z;
  if (!spike && !drop) continue;
  const severity = Math.max(zS, -zR) >= 1.5 * Z ? 'high' : 'medium';
  const lines = [];
  if (spike) lines.push(`Spend ${r2(cur.spend)} vs ${r2(sM)} baseline average (z = ${r2(zS)})`);
  if (drop) lines.push(`ROAS ${r2(roas)} vs ${r2(rM)} baseline average (z = ${r2(zR)})`);
  const type = spike && drop ? 'SPEND_SPIKE_AND_ROAS_DROP' : spike ? 'SPEND_SPIKE' : 'ROAS_DROP';
  findings.push({ type, severity, platform: c.platform, campaign: c.name, lines });
  if (TARGET > 0 && roas < TARGET) {
    actions.push({ kind: 'action', actionId: `${latest}-${c.platform}-${c.id}`, proposedAction: 'PAUSE_CAMPAIGN', platform: c.platform, campaignId: c.id, campaignName: c.name, severity,
      emailSubject: `[Approval needed] Pause ${LABEL[c.platform]} campaign: ${c.name}`,
      emailBody: `Campaign: ${c.name} (${LABEL[c.platform]}, ID ${c.id})\nDate analysed: ${latest}\n\n${lines.join('\n')}\nTarget ROAS: ${TARGET}\n\nProposed action: PAUSE this campaign.\n${cfg.dryRun ? 'DRY RUN is ON: approving will only log the action. Nothing changes in the ad platform.' : 'DRY RUN is OFF: approving will pause the campaign in the ad platform.'}` });
  }
}

const month = latest.slice(0, 7), elapsed = Number(latest.slice(8, 10));
const dim = new Date(Number(latest.slice(0, 4)), Number(latest.slice(5, 7)), 0).getDate();
const budgets = { google_ads: n(cfg.googleMonthlyBudget), meta_ads: n(cfg.metaMonthlyBudget) };
const summary = [];
for (const p of ['google_ads', 'meta_ads']) {
  const pr = ads.filter((r) => r.platform === p);
  if (!pr.length) { summary.push(`${LABEL[p]}: no data returned this run (skipped)`); continue; }
  const y = pr.filter((r) => r.date === latest);
  const ySpend = y.reduce((s, r) => s + n(r.spend), 0), yRev = y.reduce((s, r) => s + n(r.revenue), 0);
  summary.push(`${LABEL[p]} on ${latest}: spend ${r2(ySpend)}, revenue ${r2(yRev)}, ROAS ${ySpend ? r2(yRev / ySpend) : 'n/a'}`);
  const mtd = pr.filter((r) => r.date.startsWith(month)).reduce((s, r) => s + n(r.spend), 0);
  if (budgets[p] > 0 && elapsed >= 3) {
    const projected = (mtd / elapsed) * dim, ratio = projected / budgets[p];
    if (ratio > n(cfg.overPaceThreshold) || ratio < n(cfg.underPaceThreshold)) {
      const over = ratio > 1;
      findings.push({ type: over ? 'BUDGET_OVERPACE' : 'BUDGET_UNDERPACE', severity: 'medium', platform: p, campaign: 'Account level',
        lines: [`Month-to-date spend ${r2(mtd)}, projected month-end ${r2(projected)} vs budget ${budgets[p]} (${Math.round(ratio * 100)}% of budget). Advice only: review daily budgets manually.`] });
    }
  }
  const clicks = {}, sess = {};
  pr.forEach((r) => { clicks[r.date] = (clicks[r.date] || 0) + n(r.clicks); });
  ga.filter((g) => g.channel === p).forEach((g) => { sess[g.date] = (sess[g.date] || 0) + n(g.sessions); });
  const ds = dates.filter((d) => clicks[d] > 0 && sess[d] !== undefined);
  const histD = ds.filter((d) => d < latest).slice(-BASE);
  if (ds.includes(latest) && histD.length >= 7 && clicks[latest] >= 50) {
    const base = mean(histD.map((d) => sess[d] / clicks[d])), cur = sess[latest] / clicks[latest];
    if (cur < n(cfg.trackingDropRatio || 0.5) * base) {
      findings.push({ type: 'TRACKING_GAP', severity: 'high', platform: p, campaign: 'Account level',
        lines: [`GA4 sessions per ad click fell to ${r2(cur)} from a ${r2(base)} baseline. Check landing pages, UTM/auto-tagging and the GA4 tag. Advice only.`] });
    }
  }
}

const sevOrder = { high: 0, medium: 1 };
findings.sort((a, b) => sevOrder[a.severity] - sevOrder[b.severity]);
const body = [`Ad monitor digest for ${latest}`, '', ...summary, '',
  findings.length ? `Findings (${findings.length}):` : 'No anomalies, pacing or tracking issues detected.',
  ...findings.map((f, i) => `${i + 1}. [${f.severity.toUpperCase()}] ${f.type} - ${LABEL[f.platform]} / ${f.campaign}\n   ${f.lines.join('\n   ')}`),
  '', actions.length ? `${actions.length} action(s) are waiting for your approval in separate emails.` : 'No actions need approval.'].join('\n');

return [{ json: { kind: 'digest', subject: `Ad monitor ${latest}: ${findings.length} finding(s)`, body, counts: { findings: findings.length, actions: actions.length }, findings } },
  ...actions.map((a) => ({ json: a }))];

const n = (x) => Number(x) || 0;
const out = [];
const META_ACTIONS = ['omni_purchase', 'purchase', 'offsite_conversion.fb_pixel_purchase', 'lead'];
const pickAction = (list) => {
  for (const t of META_ACTIONS) { const a = (list || []).find((x) => x.action_type === t); if (a) return n(a.value); }
  return 0;
};
const gaDate = (s) => `${s.slice(0, 4)}-${s.slice(4, 6)}-${s.slice(6, 8)}`;

for (const it of $input.all()) {
  const j = it.json;
  if (Array.isArray(j.results)) {
    for (const r of j.results) {
      out.push({ type: 'ads', platform: 'google_ads', date: r.segments.date, campaignId: String(r.campaign.id), campaignName: r.campaign.name,
        spend: n(r.metrics.costMicros) / 1e6, clicks: n(r.metrics.clicks), impressions: n(r.metrics.impressions),
        conversions: n(r.metrics.conversions), revenue: n(r.metrics.conversionsValue) });
    }
  } else if (Array.isArray(j.data)) {
    for (const r of j.data) {
      out.push({ type: 'ads', platform: 'meta_ads', date: r.date_start, campaignId: String(r.campaign_id), campaignName: r.campaign_name,
        spend: n(r.spend), clicks: n(r.clicks), impressions: n(r.impressions),
        conversions: pickAction(r.actions), revenue: pickAction(r.action_values) });
    }
  } else if (Array.isArray(j.rows)) {
    for (const r of j.rows) {
      const date = gaDate(r.dimensionValues[0].value);
      const [source, medium] = r.dimensionValues[1].value.split(' / ').map((s) => (s || '').toLowerCase());
      const paid = /cpc|paid|ppc/.test(medium || '');
      let channel = null;
      if (paid && /google/.test(source)) channel = 'google_ads';
      else if (paid && /(facebook|fb|instagram|ig|meta)/.test(source)) channel = 'meta_ads';
      if (!channel) continue;
      out.push({ type: 'ga4', channel, date, sessions: n(r.metricValues[0].value), conversions: n(r.metricValues[1].value), revenue: n(r.metricValues[2].value) });
    }
  }
}
const merged = {};
for (const r of out) {
  const k = r.type === 'ads' ? `a|${r.platform}|${r.campaignId}|${r.date}` : `g|${r.channel}|${r.date}`;
  if (!merged[k]) { merged[k] = { ...r }; continue; }
  for (const f of ['spend', 'clicks', 'impressions', 'conversions', 'revenue', 'sessions']) if (r[f] !== undefined) merged[k][f] = n(merged[k][f]) + n(r[f]);
}
return Object.values(merged).map((r) => ({ json: r }));
